// A stand-in for the Sass compiler (only what this test needs: `$name: value;` and `$name` in values, and nesting of one level is not done), so the test needs no download.
exports.compileStringAsync = async (code, { url, syntax }) => {
  const vars = {};
  const body = code.replace(/^\$([\w-]+):\s*([^;]+);\s*$/gm, (_, name, value) => ((vars[name] = value), '')).replace(/\$([\w-]+)/g, (_, name) => vars[name]);
  return { css: `/* ${syntax} */\n` + body.trim() + '\n', loadedUrls: [url] };
};
